-- Friends, opt-in: a profile only for learners who turn friends on in
-- Settings (every share defaults off), and one row per pair of friends.
-- Connection is by a code the other person chose to give out; there is no
-- search. Turning friends off deletes the profile and, by cascade, every
-- friendship.
--
-- Generated by drizzle-kit, then made idempotent by hand. Additive: two new
-- tables, nothing existing touched.

CREATE TABLE IF NOT EXISTS "friend_profiles" (
	"user_id" text PRIMARY KEY NOT NULL,
	"display_name" text NOT NULL,
	"code" text NOT NULL,
	"share_studied_today" boolean DEFAULT false NOT NULL,
	"share_crossword" boolean DEFAULT false NOT NULL,
	"share_weekly" boolean DEFAULT false NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "friendships" (
	"id" text PRIMARY KEY NOT NULL,
	"requester_id" text NOT NULL,
	"addressee_id" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"accepted_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "friendships_not_self" CHECK ("friendships"."requester_id" <> "friendships"."addressee_id")
);
--> statement-breakpoint
